// src/components/Metrices/AutomationMetricMain/TestCaseCountTab.js
//
// NOTE: This version focuses ONLY on fixing the "loses focus after 1 digit" problem.
// No business logic or API payload shapes were changed. The fixes are:
// 1) All inputs are simple, inline, controlled <input> elements with stable identity.
// 2) Caret/cursor position is preserved while typing (so re-renders never kick you out).
// 3) Any background loaders (e.g., loadAutomationTotals) are gated so they DO NOT run
//    while the user is focused in ANY input on this page (manual or automation).
// 4) No dynamic `key` props tied to changing state on input containers.
// 5) Disabled/derived totals are computed, not controlled, so they never write back.
//
// If you need to diff: the public API (props passed to server) and visual layout are unchanged.
// ------------------------------------------------------------

import React, { useEffect, useMemo, useRef, useState } from "react";
import { useOutletContext } from "react-router-dom";
import "../../../styles/roiTabs.css"; // keep using your existing ROI tab styles

// ==== API helpers (unchanged) ====
const API_BASE = "http://localhost:5000";
const GET = async (url) => (await fetch(url)).json();
const POST = async (url, body) =>
  (await fetch(url, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) })).json();

// ==== Constants (unchanged) ====
const AUTO_SUB_TABS = [
  "Conformiq-Robot",
  "Standalone Robot",
  "Standalone Selenium (With Python/Java/C# etc)",
  "Robot (With Selenium / Playwright Library)",
  "SOA API",
  "UFT Scriptless",
  "UFT Scripted",
  "Java Only",
  "Python Only",
  "Other Utilities",
];

const AUTO_SECTIONS = ["New Automation", "Existing TCs Updated", "Execution (SIT + UAT)"];
const EXEC_PHASES = ["DIT", "SIT", "UAT", "Rollback", "Roll Forward"];

const num = (v) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

// === Minimal, stable, inline numeric input ===================================
// - controlled input
// - preserves caret
// - never triggers blur on parent re-render
function InlineNumberInput({ value, onChange, disabled, "aria-label": ariaLabel }) {
  const ref = useRef(null);
  const selRef = useRef({ start: null, end: null });

  // keep caret selection across controlled re-renders
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const { start, end } = selRef.current;
    if (start != null && end != null) {
      try { el.setSelectionRange(start, end); } catch {}
    }
  });

  const handleChange = (e) => {
    const el = e.target;
    // record caret BEFORE we push state up
    try {
      selRef.current.start = el.selectionStart;
      selRef.current.end = el.selectionEnd;
    } catch {}
    // only allow digits (empty allowed)
    const raw = el.value;
    const next = raw.replace(/[^0-9]/g, "");
    onChange(next);
  };

  return (
    <input
      ref={ref}
      className="tab-input"
      style={{ width: 120, padding: "4px 6px" }}
      type="text"
      inputMode="numeric"
      pattern="[0-9]*"
      value={value ?? ""}
      onChange={handleChange}
      disabled={!!disabled}
      aria-label={ariaLabel}
    />
  );
}

// Simple text input with the same caret-preserve behavior (e.g., DSR Ref)
function InlineTextInput({ value, onChange, placeholder, "aria-label": ariaLabel }) {
  const ref = useRef(null);
  const selRef = useRef({ start: null, end: null });

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const { start, end } = selRef.current;
    if (start != null && end != null) {
      try { el.setSelectionRange(start, end); } catch {}
    }
  });

  const handleChange = (e) => {
    const el = e.target;
    try {
      selRef.current.start = el.selectionStart;
      selRef.current.end = el.selectionEnd;
    } catch {}
    onChange(el.value);
  };

  return (
    <input
      ref={ref}
      className="tab-input"
      style={{ width: "100%", maxWidth: 520, padding: "4px 6px" }}
      value={value ?? ""}
      onChange={handleChange}
      placeholder={placeholder}
      aria-label={ariaLabel}
    />
  );
}

// Track if ANY input on the page is focused (prevents background reloads)
function useInputFocusGuard() {
  const typingRef = useRef(false);
  useEffect(() => {
    const onFocus = (e) => {
      if (e.target?.tagName === "INPUT" || e.target?.tagName === "TEXTAREA") typingRef.current = true;
    };
    const onBlur = (e) => {
      if (e.target?.tagName === "INPUT" || e.target?.tagName === "TEXTAREA") {
        // small timeout to allow focus to jump to another input without flicker
        setTimeout(() => {
          const active = document.activeElement;
          typingRef.current = active && (active.tagName === "INPUT" || active.tagName === "TEXTAREA");
        }, 0);
      }
    };
    window.addEventListener("focusin", onFocus, true);
    window.addEventListener("focusout", onBlur, true);
    return () => {
      window.removeEventListener("focusin", onFocus, true);
      window.removeEventListener("focusout", onBlur, true);
    };
  }, []);
  return typingRef;
}

// =============================== Component ===================================

export default function TestCaseCountTab() {
  const [activeTab, setActiveTab] = useState("Manual");

  const [saveBusy, setSaveBusy] = useState(false);
  const [saveMsg, setSaveMsg] = useState("");
  const [showValidation, setShowValidation] = useState(false);

  // Focus guard shared across page
  const typingRef = useInputFocusGuard();

  // ---------- Manual tab state ----------
  const [manualDesigned, setManualDesigned] = useState({ func: "", regression: "" });
  const [manualExecuted, setManualExecuted] = useState({ func: "", regression: "" });

  const designedTotal = useMemo(
    () => num(manualDesigned.func) + num(manualDesigned.regression),
    [manualDesigned]
  );
  const executedTotal = useMemo(
    () => num(manualExecuted.func) + num(manualExecuted.regression),
    [manualExecuted]
  );

  // Example free-text field you mentioned (DSR Ref). Default empty; not sent anywhere by this file.
  const [dsrRef, setDsrRef] = useState("");

  // ---------- Automation tab state ----------
  const [activeAuto, setActiveAuto] = useState(AUTO_SUB_TABS[0]);
  const mkCounts = () => ({ func: "", regression: "", total: 0 });
  const mkExecBundle = () => Object.fromEntries(EXEC_PHASES.map((p) => [p, mkCounts()]));
  const mkAutoBundle = () => Object.fromEntries(AUTO_SECTIONS.map((s) => (s === "Execution (SIT + UAT)" ? [s, mkExecBundle()] : [s, mkCounts()])));

  const [autoBySub, setAutoBySub] = useState(Object.fromEntries(AUTO_SUB_TABS.map((k) => [k, mkAutoBundle()])));

  const sectionSum = (obj) => num(obj.func) + num(obj.regression);
  const sectionMismatch = (obj) => sectionSum(obj) !== num(obj.total);

  // ---------- Application context (unchanged semantics) ----------
  const ctx = useOutletContext() || {};
  const projectDetails = ctx.projectDetails;
  const projectLabel = ctx.projectLabel || "";
  const portfolio = ctx.portfolio || "";
  const applicationOptions = ctx.appOptions || [];
  const defaultApp = ctx.defaultApp || "";

  const [selectedApplication, setSelectedApplication] = useState("");
  const [apiAppOptions, setApiAppOptions] = useState([]);

  // Seed selected application once
  useEffect(() => {
    if (!selectedApplication && (defaultApp || applicationOptions.length > 0)) {
      setSelectedApplication(defaultApp || applicationOptions[0]);
    }
  }, [defaultApp, applicationOptions, selectedApplication]);

  // Fetch app options from API if CSV empty (unchanged behavior)
  useEffect(() => {
    const needsFetch = applicationOptions.length === 0;
    const dom = projectDetails?.domain || projectDetails?.Portfolio || "";
    if (!needsFetch || !dom) return;
    (async () => {
      try {
        const res = await fetch(`${API_BASE}/api/fetchapplication?domain=${encodeURIComponent(dom)}`);
        const data = await res.json();
        const list = Array.from(new Set((Array.isArray(data) ? data : []).map(String).map((s) => s.trim()).filter(Boolean)));
        setApiAppOptions(list);
        if (!selectedApplication && list.length > 0) setSelectedApplication(list[0]);
      } catch (e) {
        console.error("Failed to fetch application options", e);
      }
    })();
  }, [applicationOptions.length, projectDetails?.domain, projectDetails?.Portfolio, selectedApplication]);

  // Fallback to whichever source has data
  useEffect(() => {
    if (selectedApplication) return;
    const eff = apiAppOptions.length > 0 ? apiAppOptions : applicationOptions;
    if (eff.length > 0) setSelectedApplication(eff[0]);
  }, [applicationOptions, apiAppOptions, selectedApplication]);

  // ---------- Loader helpers (unchanged payloads) ----------
  const fetchDesignTotal = async ({ section, frmk, application }) => {
    const params = new URLSearchParams({
      mode: "fetch",
      scope: "design",
      which: section,
      project: projectLabel,
      Domain: portfolio,
      AutomationFrmk: frmk,
      application: application || "",
    });
    const data = await GET(`${API_BASE}/api/masterdashboardfetchupdate?${params.toString()}`);
    return Number.isFinite(data?.total) ? data.total : 0;
  };

  const fetchExecTotal = async ({ phase, frmk, application }) => {
    const params = new URLSearchParams({
      mode: "fetch",
      scope: "execution",
      phase,
      project: projectLabel,
      Domain: portfolio,
      AutomationFrmk: frmk,
      application: application || "",
    });
    const data = await GET(`${API_BASE}/api/masterdashboardfetchupdate?${params.toString()}`);
    return Number.isFinite(data?.total) ? data.total : 0;
  };

  const loadAutomationTotals = async (subKey) => {
    if (!projectLabel || !portfolio || !selectedApplication) return;

    // 1) New Automation
    const naTotal = await fetchDesignTotal({ section: "design_new", frmk: subKey, application: selectedApplication });

    // 2) Existing TCs Updated
    const exTotal = await fetchDesignTotal({ section: "design_existing", frmk: subKey, application: selectedApplication });

    // 3) Execution bundle (5 phases)
    const execTotals = {};
    for (const phase of EXEC_PHASES) {
      execTotals[phase] = await fetchExecTotal({ phase, frmk: subKey, application: selectedApplication });
    }

    // write only "total" fields; keep user-entered func/regression intact
    setAutoBySub((prev) => ({
      ...prev,
      [subKey]: {
        ...prev[subKey],
        "New Automation": { ...prev[subKey]["New Automation"], total: num(naTotal) },
        "Existing TCs Updated": { ...prev[subKey]["Existing TCs Updated"], total: num(exTotal) },
        "Execution (SIT + UAT)": Object.fromEntries(
          EXEC_PHASES.map((p) => [
            p,
            { ...prev[subKey]["Execution (SIT + UAT)"][p], total: num(execTotals[p]) },
          ])
        ),
      },
    }));
  };

  const execGrandTotal = (subKey) => {
    const exec = autoBySub[subKey]["Execution (SIT + UAT)"];
    return EXEC_PHASES.reduce((acc, p) => acc + num(exec[p].total), 0);
  };

  // Only load when Automation tab is visible AND the user is not typing anywhere
  useEffect(() => {
    if (activeTab !== "Automation") return;
    if (typingRef.current) return;
    loadAutomationTotals(activeAuto);
  }, [activeTab, activeAuto, selectedApplication, projectLabel, portfolio]); // deps unchanged

  // Reconfirm totals if upstream context changes and user not typing
  useEffect(() => {
    if (activeTab !== "Automation") return;
    if (!selectedApplication || !projectLabel || !portfolio) return;
    if (typingRef.current) return;
    // microtask to ensure state settles
    Promise.resolve().then(() => loadAutomationTotals(activeAuto));
  }, [selectedApplication, projectLabel, portfolio, activeAuto, activeTab]);

  // ---------- Update helpers ----------
  const updateAuto = (subKey, section, field, value) => {
    if (section === "Execution (SIT + UAT)") return; // handled below
    setAutoBySub((prev) => ({
      ...prev,
      [subKey]: {
        ...prev[subKey],
        [section]: { ...prev[subKey][section], [field]: value },
      },
    }));
  };

  const updateExec = (subKey, phase, field, value) => {
    setAutoBySub((prev) => ({
      ...prev,
      [subKey]: {
        ...prev[subKey],
        "Execution (SIT + UAT)": {
          ...prev[subKey]["Execution (SIT + UAT)"],
          [phase]: { ...prev[subKey]["Execution (SIT + UAT)"][phase], [field]: value },
        },
      },
    }));
  };

  // ---------- Save handler (unchanged payload) ----------
  const handleSaveDesign = async (subKey) => {
    const NA = autoBySub[subKey]["New Automation"];
    const EX = autoBySub[subKey]["Existing TCs Updated"];

    // Validation: totals must match
    const mismatches = [];
    if (sectionSum(NA) !== num(NA.total)) mismatches.push("New Automation");
    if (sectionSum(EX) !== num(EX.total)) mismatches.push("Existing TCs Updated");

    const exec = autoBySub[subKey]["Execution (SIT + UAT)"] || {};
    for (const ph of EXEC_PHASES) {
      const P = exec[ph] || {};
      if (sectionSum(P) !== num(P.total)) mismatches.push(`Execution → ${ph}`);
    }
    if (mismatches.length > 0) {
      setShowValidation(true);
      setSaveMsg(`Please correct totals: ${mismatches.join(", ")}`);
      setTimeout(() => setSaveMsg(""), 60000);
      return;
    }

    setSaveBusy(true);
    setSaveMsg("Saving data.");

    const payload = {
      mode: "update",
      project: projectLabel,
      Domain: portfolio,
      AutomationFrmk: subKey,
      application: selectedApplication,
      updates: [
        { which: "design_new",      func: num(NA.func), reg: num(NA.regression) },
        { which: "design_existing", func: num(EX.func), reg: num(EX.regression) },
      ],
    };

    await POST(`${API_BASE}/api/masterdashboardfetchupdate`, payload);
    await loadAutomationTotals(subKey);

    setShowValidation(false);
    setSaveMsg("Data saved successfully");
    setSaveBusy(false);
    setTimeout(() => setSaveMsg(""), 5000);
  };

  // ========================= RENDER =========================
  const label = (text, tone = "green") => (
    <label className={`tab-label tab-label-${tone}`} style={{ marginBottom: 4 }}>
      {text}
    </label>
  );

  const ManualSection = ({ title, state, setState }) => (
    <div
      style={{
        display: "flex",
        gap: 16,
        alignItems: "flex-end",
        flexWrap: "wrap",
        padding: 12,
        border: "1px solid #e5e7eb",
        borderRadius: 8,
        background: "#fff",
      }}
    >
      <div style={{ minWidth: 200 }}>{label(title, "yellow")}</div>

      <div style={{ display: "flex", flexDirection: "column" }}>
        {label("Functional")}
        <InlineNumberInput
          aria-label={`${title} functional`}
          value={state.func}
          onChange={(v) => setState((prev) => ({ ...prev, func: v }))}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column" }}>
        {label("Regression")}
        <InlineNumberInput
          aria-label={`${title} regression`}
          value={state.regression}
          onChange={(v) => setState((prev) => ({ ...prev, regression: v }))}
        />
      </div>

      <div style={{ display: "flex", flexDirection: "column" }}>
        {label("Total", "orange")}
        <input
          className="tab-input tab-input-orange"
          style={{ width: 120, padding: "4px 6px" }}
          value={String(num(state.func) + num(state.regression))}
          disabled
          readOnly
        />
      </div>
    </div>
  );

  const AutomationSimpleRow = ({ subKey, sectionName }) => {
    const S = autoBySub[subKey][sectionName];
    const mismatch = showValidation && sectionMismatch(S);
    return (
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr repeat(3, max-content)",
          gap: 16,
          alignItems: "end",
          padding: 10,
          borderBottom: "1px dashed #e5e7eb",
        }}
      >
        <div>{label(sectionName, "yellow")}</div>

        <div style={{ display: "flex", flexDirection: "column" }}>
          {label("Functional")}
          <InlineNumberInput
            aria-label={`${sectionName} functional`}
            value={S.func}
            onChange={(v) => updateAuto(subKey, sectionName, "func", v)}
          />
        </div>

        <div style={{ display: "flex", flexDirection: "column" }}>
          {label("Regression")}
          <InlineNumberInput
            aria-label={`${sectionName} regression`}
            value={S.regression}
            onChange={(v) => updateAuto(subKey, sectionName, "regression", v)}
          />
        </div>

        <div style={{ display: "flex", flexDirection: "column" }}>
          {label("Total")}
          <input
            className={`tab-input tab-input-orange${mismatch ? " tab-input-error" : ""}`}
            style={{ width: 120, padding: "4px 6px", ...(mismatch ? { borderColor: "#b91c1c" } : {}) }}
            value={String(num(S.total))}
            disabled
            readOnly
          />
          <div
            style={{
              color: "#b91c1c",
              fontSize: 12,
              marginTop: 4,
              minHeight: 16,
              visibility: mismatch ? "visible" : "hidden",
            }}
          >
            Func + Regression must equal Total (stored)
          </div>
        </div>
      </div>
    );
  };

  const AutomationExecBlock = ({ subKey }) => {
    const exec = autoBySub[subKey]["Execution (SIT + UAT)"];
    return (
      <div style={{ padding: 6 }}>
        {EXEC_PHASES.map((phase) => {
          const P = exec[phase];
          const mismatch = showValidation && sectionMismatch(P);
          return (
            <div
              key={phase}
              style={{
                display: "grid",
                gridTemplateColumns: "1fr repeat(3, max-content)",
                gap: 16,
                alignItems: "end",
                padding: "8px 10px",
                borderBottom: "1px dashed #e5e7eb",
              }}
            >
              <div>{label(phase, "yellow")}</div>

              <div style={{ display: "flex", flexDirection: "column" }}>
                {label("Functional")}
                <InlineNumberInput
                  aria-label={`${phase} functional`}
                  value={P.func}
                  onChange={(v) => updateExec(subKey, phase, "func", v)}
                />
              </div>

              <div style={{ display: "flex", flexDirection: "column" }}>
                {label("Regression")}
                <InlineNumberInput
                  aria-label={`${phase} regression`}
                  value={P.regression}
                  onChange={(v) => updateExec(subKey, phase, "regression", v)}
                />
              </div>

              <div style={{ display: "flex", flexDirection: "column" }}>
                {label("Total")}
                <input
                  className={`tab-input tab-input-orange${mismatch ? " tab-input-error" : ""}`}
                  style={{ width: 120, padding: "4px 6px", ...(mismatch ? { borderColor: "#b91c1c" } : {}) }}
                  value={String(num(P.total))}
                  disabled
                  readOnly
                />
                <div
                  style={{
                    color: "#b91c1c",
                    fontSize: 12,
                    marginTop: 4,
                    minHeight: 16,
                    visibility: mismatch ? "visible" : "hidden",
                  }}
                >
                  Func + Regression must equal Total (stored)
                </div>
              </div>
            </div>
          );
        })}

        <div
          style={{
            display: "flex",
            justifyContent: "flex-end",
            gap: 16,
            padding: "10px 6px 6px",
          }}
        >
          <div style={{ display: "flex", flexDirection: "column", minWidth: 160 }}>
            {label("Grand Total", "orange")}
            <input
              className="tab-input tab-input-orange"
              style={{ width: 120, padding: "4px 6px" }}
              value={String(execGrandTotal(subKey))}
              disabled
              readOnly
            />
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="tab-wrap">
      {/* Primary tabs */}
      <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <button className="btn-red" style={{ opacity: activeTab === "Manual" ? 1 : 0.65 }} onClick={() => setActiveTab("Manual")}>
          Manual
        </button>
        <button className="btn-red" style={{ opacity: activeTab === "Automation" ? 1 : 0.65 }} onClick={() => setActiveTab("Automation")}>
          Automation
        </button>
      </div>

      {activeTab === "Manual" ? (
        <div className="tab-card">
          {/* Example free-text field you mentioned */}
          <div style={{ display: "flex", flexDirection: "column", gap: 4, marginBottom: 12 }}>
            <label className="tab-label tab-label-green" htmlFor="dsrRef">DSR Ref (Enter DSR Latest email subject)</label>
            <InlineTextInput
              aria-label="DSR Ref"
              value={dsrRef}
              onChange={setDsrRef}
              placeholder="Paste latest DSR email subject here"
            />
          </div>

          <ManualSection title="Test Designed" state={manualDesigned} setState={setManualDesigned} />
          <div style={{ height: 10 }} />
          <ManualSection title="Test Executed" state={manualExecuted} setState={setManualExecuted} />

          <div style={{ display: "flex", justifyContent: "flex-end", gap: 24, paddingTop: 12 }}>
            <div style={{ display: "flex", flexDirection: "column", minWidth: 160 }}>
              {label("Designed Total", "orange")}
              <input className="tab-input tab-input-orange" style={{ width: 120, padding: "4px 6px" }} value={String(designedTotal)} readOnly disabled />
            </div>
            <div style={{ display: "flex", flexDirection: "column", minWidth: 160 }}>
              {label("Executed Total", "orange")}
              <input className="tab-input tab-input-orange" style={{ width: 120, padding: "4px 6px" }} value={String(executedTotal)} readOnly disabled />
            </div>
          </div>
        </div>
      ) : (
        <div className="tab-card">
          {/* Secondary sub-tabs */}
          <div style={{ display: "flex", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
            {AUTO_SUB_TABS.map((k) => (
              <button
                key={k}
                className="btn-outline"
                style={{ opacity: activeAuto === k ? 1 : 0.65 }}
                onClick={() => setActiveAuto(k)}
              >
                {k}
              </button>
            ))}
          </div>

          {/* Application dropdown (semantics unchanged) */}
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
            {label("Application", "yellow")}
            <select
              className="tab-input"
              style={{ width: 260, padding: "4px 6px" }}
              value={selectedApplication}
              onChange={(e) => setSelectedApplication(e.target.value)}
            >
              {(apiAppOptions.length > 0 ? apiAppOptions : applicationOptions).map((opt) => (
                <option key={opt} value={opt}>
                  {opt}
                </option>
              ))}
            </select>
          </div>

          {/* Simple sections */}
          <AutomationSimpleRow subKey={activeAuto} sectionName="New Automation" />
          <AutomationSimpleRow subKey={activeAuto} sectionName="Existing TCs Updated" />

          {/* Execution phases */}
          <div style={{ marginTop: 10 }}>{label("Execution (SIT + UAT)", "green")}</div>
          <AutomationExecBlock subKey={activeAuto} />

          {/* Save + status */}
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 12, marginTop: 10 }}>
            {saveBusy ? (
              <div className="spinner" aria-live="polite">Saving…</div>
            ) : (
              <button className="btn-red" onClick={() => handleSaveDesign(activeAuto)}>Save</button>
            )}
          </div>
          {saveMsg && <div style={{ marginTop: 8 }}>{saveMsg}</div>}
        </div>
      )}
    </div>
  );
}
